// Time-based 1.6x movement. Every attempted terrain step remains exactly one pixel.
export const MOTION=Object.freeze({pixelsPerSecond:192,maxDeltaMs:100});
export function createMotionIntegrator(){let rx=0,ry=0,lastX=0,lastY=0;return Object.freeze({reset(){rx=ry=lastX=lastY=0},advance(directions,deltaMs,move){if(!Number.isFinite(deltaMs)||deltaMs<0)throw Error('FEEDBACK_DELTA');const s=new Set(directions),x=Number(s.has('right'))-Number(s.has('left')),y=Number(s.has('down'))-Number(s.has('up'));if(x!==lastX)rx=0;if(y!==lastY)ry=0;lastX=x;lastY=y;if(!x&&!y){rx=ry=0;return Object.freeze({attempts:0,moved:0,deltaMs:0})}const dt=Math.min(deltaMs,100),scale=192*dt/1000/Math.hypot(x,y);rx+=x*scale;ry+=y*scale;let nx=Math.sign(rx)*Math.floor(Math.abs(rx)+1e-10),ny=Math.sign(ry)*Math.floor(Math.abs(ry)+1e-10);rx-=nx;ry-=ny;let attempts=0,moved=0;while(nx||ny){if(nx){const dir=nx>0?'right':'left';attempts++;if(move(dir))moved++;else{rx=0;nx=0}if(nx)nx-=Math.sign(nx)}if(ny){const dir=ny>0?'down':'up';attempts++;if(move(dir))moved++;else{ry=0;ny=0}if(ny)ny-=Math.sign(ny)}}return Object.freeze({attempts,moved,deltaMs:dt})}})}
